import Avatar from "./Avatar";
import useSearchUsers from "../hooks/useSearchUsers";
import { uploadMessageMedia } from "../js/supabaseUpload";
import Picker from "emoji-picker-react";

function makeRoomId(a, b) {
    return [a, b].sort().join("_");
}

function formatTime(ts) {
    if (!ts) return "";
    const d = ts?.toDate ? ts.toDate() : new Date(ts);
    return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

export default function PrivateChat({ currentUser, otherUser, onClose }) {

    const roomId = makeRoomId(currentUser.uid, otherUser.id);

    const { allUsers } = useSearchUsers();
    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");

    const [file, setFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState("");

    const [uploading, setUploading] = useState(false);

    // edição
    const [editingMessage, setEditingMessage] = useState(null);
    const [editText, setEditText] = useState("");

    // emoji
    const [showEmoji, setShowEmoji] = useState(false);

    // GIF
    const [showGifModal, setShowGifModal] = useState(false);
    const [gifUrl, setGifUrl] = useState("");

    // menu flutuante mensagem
    const [openMenuId, setOpenMenuId] = useState(null);

    const listRef = useRef(null);


    /** 🔄 CARREGA CHAT + MARCA COMO RECEBIDAS/VISTAS */
    useEffect(() => {
        let unsub;

        const setupChat = async () => {

            const roomRef = doc(db, "rooms", roomId);
            const snap = await getDoc(roomRef);

            if (!snap.exists()) {
                await setDoc(roomRef, {
                    members: [currentUser.uid, otherUser.id],
                    createdAt: serverTimestamp(),
                    lastMessage: "",
                    lastUpdated: serverTimestamp()
                });
            }

            const messagesRef = collection(db, `rooms/${roomId}/messages`);
            const q = query(messagesRef, orderBy("createdAt", "asc"));

            unsub = onSnapshot(q, async (s) => {
                const arr = s.docs.map(d => ({ id: d.id, ...d.data() }));
                setMessages(arr);

                // marcar recebidas
                const updates = [];
                for (let d of s.docs) {
                    const data = d.data();
                    if (!data) continue;

                    if (data.from !== currentUser.uid && data.status === "sent") {
                        updates.push(updateDoc(d.ref, { status: "received" }));
                    }
                }
                if (updates.length) await Promise.all(updates);

                // scroll bottom
                setTimeout(() => {
                    if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
                }, 40);
            });

            await markMessagesAsSeen();
        };

        setupChat();

        return () => {
            if (unsub) unsub();
        };

    }, [roomId, currentUser.uid, otherUser.id]);


    /** 👁 MARCAR COMO VISTAS */
    async function markMessagesAsSeen() {
        try {
            const messagesRef = collection(db, `rooms/${roomId}/messages`);
            const q = query(messagesRef, where("from", "!=", currentUser.uid));
            const snap = await getDocs(q);

            const updates = [];

            for (let d of snap.docs) {
                const data = d.data();
                if (!data) continue;

                const seenBy = data.seenBy || [];
                if (!seenBy.includes(currentUser.uid)) {
                    updates.push(updateDoc(d.ref, {
                        seenBy: arrayUnion(currentUser.uid),
                        status: "seen"
                    }));
                }
            }

            if (updates.length) await Promise.all(updates);

        } catch (err) {
            console.log("Erro seen:", err);
        }
    }


    /** 📤 ENVIAR TEXTO + MÍDIA */
    const send = async () => {
        if (!text.trim() && !file) return;

        setUploading(true);

        try {
            let url = "";
            let type = "text";

            // upload mídia
            if (file) {
                url = await uploadMessageMedia(file, roomId);
                const lower = file.type.toLowerCase();

                if (lower.startsWith("image/")) type = "image";
                else if (lower.startsWith("video/")) type = "video";
                else if (lower.startsWith("audio/")) type = "audio";
                else type = "file";
            }

            // create message
            await addDoc(collection(db, `rooms/${roomId}/messages`), {
                text: text.trim(),
                url,
                type,
                from: currentUser.uid,
                createdAt: serverTimestamp(),
                status: "sent",
                seenBy: []
            });

            // update room last msg
            await updateDoc(doc(db, "rooms", roomId), {
                lastMessage: text.trim() || (type === "image" ? "[imagem]" :
                    type === "video" ? "[vídeo]" :
                        type === "audio" ? "[áudio]" :
                            "[arquivo]"),
                lastUpdated: serverTimestamp()
            });

            // limpar
            setText("");
            setFile(null);
            if (previewUrl) URL.revokeObjectURL(previewUrl);
            setPreviewUrl("");

        } catch (err) {
            alert("Erro ao enviar: " + err.message);
        }

        setUploading(false);
    };


    /** 📁 SELECIONAR ARQUIVO */
    const onSelectFile = (e) => {
        const f = e.target.files[0];
        if (!f) return;

        if (f.size > 40 * 1024 * 1024) {
            return alert("Arquivo muito grande (máx 40MB)");
        }

        setFile(f);
        setPreviewUrl(URL.createObjectURL(f));
    };


    /** ✏️ INICIAR EDIÇÃO */
    const startEditing = (msg) => {
        const created = msg.createdAt?.toDate()?.getTime() || 0;
        if (Date.now() - created > 5 * 60 * 1000) {
            return alert("Só pode editar até 5 min após o envio.");
        }

        setEditingMessage(msg);
        setEditText(msg.text);
        setText(msg.text);
    };


    /** ✔️ SALVAR EDIÇÃO */
    const saveEdit = async () => {
        if (!editingMessage) return;

        await updateDoc(doc(db, `rooms/${roomId}/messages`, editingMessage.id), {
            text: editText.trim(),
            edited: true,
            editedAt: serverTimestamp()
        });

        setEditingMessage(null);
        setEditText("");
        setText("");
    };


    /** ❌ CANCELAR EDIÇÃO */
    const cancelEdit = () => {
        setEditingMessage(null);
        setEditText("");
        setText("");
    };


    /** 🗑 EXCLUIR PARA MIM */
    const deleteForMe = async (msg) => {
        await updateDoc(doc(db, `rooms/${roomId}/messages`, msg.id), {
            deletedFor: arrayUnion(currentUser.uid)
        });
    };


    /** 🚫 EXCLUIR PARA TODOS */
    const deleteForAll = async (msg) => {
        const seen = msg.seenBy || [];
        if (seen.length > 0) {
            return alert("Não pode excluir: destinatário já viu.");
        }

        await updateDoc(doc(db, `rooms/${roomId}/messages`, msg.id), {
            deletedForAll: true,
            text: "",
            url: "",
            type: "text",
            edited: false,
            deletedAt: serverTimestamp()
        });
    };


    /** 🟦 STATUS DOS TIQUES */
    const renderStatus = (m) => {
        if (m.from !== currentUser.uid) return null;
        if (m.deletedForAll) return null;

        const st = m.status || "sent";

        if (st === "sent") return <span>✓</span>;
        if (st === "received") return <span>✓✓</span>;
        if (st === "seen") return <span style={{ color: "#1ca3ff" }}>✓✓</span>;

        return null;
    };


    const findUserById = (id) => allUsers.find(u => u.id === id);


    /** MENU DE 3 PONTOS — WHATSAPP */
    const MessageMenu = ({ msg }) => {
        if (msg.from !== currentUser.uid) return null;

        return (
            <div style={{
                position: "absolute",
                top: -5,
                right: -5,
                zIndex: 30
            }}>
                <button
                    onClick={() => setOpenMenuId(openMenuId === msg.id ? null : msg.id)}
                    style={{
                        background: "transparent",
                        border: "none",
                        fontSize: 16,
                        cursor: "pointer"
                    }}
                >
                    ⋮
                </button>

                {openMenuId === msg.id && (
                    <div style={{
                        position: "absolute",
                        right: 0,
                        top: 24,
                        background: "#fff",
                        border: "1px solid #ddd",
                        borderRadius: 8,
                        padding: "6px 0",
                        boxShadow: "0 2px 4px rgba(0,0,0,0.15)",
                        width: 120
                    }}>
                        <div className="menu-item" onClick={() => { setOpenMenuId(null); startEditing(msg); }}
                            style={{ padding: "8px 14px", cursor: "pointer" }}>
                            Editar
                        </div>

                        <div className="menu-item" onClick={() => { setOpenMenuId(null); deleteForMe(msg); }}
                            style={{ padding: "8px 14px", cursor: "pointer" }}>
                            Excluir para mim
                        </div>

                        <div className="menu-item" onClick={() => { setOpenMenuId(null); deleteForAll(msg); }}
                            style={{ padding: "8px 14px", cursor: "pointer" }}>
                            Excluir para todos
                        </div>
                    </div>
                )}
            </div>
        );
    };


    return (
        <>
            {/* HEADER */}
            <div className="chat-header">
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <button onClick={onClose} style={{ background: "transparent", border: "none", color: "#fff", fontSize: 18 }}>←</button>
                    <Avatar user={otherUser} size={44} />
                    <div>
                        <div style={{ fontWeight: 700 }}>
                            {otherUser.nome || otherUser.email}
                        </div>
                        <div style={{ fontSize: 12 }}>
                            {otherUser.email}
                        </div>
                    </div>
                </div>
            </div>


            {/* LISTA DE MENSAGENS */}
            <div className="chat-box" ref={listRef}>
                {messages.map(m => {

                    if (m.deletedFor?.includes(currentUser.uid)) return null;

                    const isMe = m.from === currentUser.uid;
                    const sender = findUserById(m.from) || otherUser;

                    if (m.deletedForAll) {
                        return (
                            <div key={m.id} style={{ margin: "6px 0", opacity: 0.7, fontStyle: "italic" }}>
                                Mensagem excluída
                            </div>
                        );
                    }

                    return (
                        <div key={m.id} style={{
                            display: "flex",
                            justifyContent: isMe ? "flex-end" : "flex-start",
                            marginBottom: 10,
                            position: "relative"
                        }}>

                            {/* Avatar do outro */}
                            {!isMe && (
                                <Avatar user={sender} size={36} style={{ marginRight: 6 }} />
                            )}

                            {/* BOLHA */}
                            <div className={`msg ${isMe ? "me" : "other"}`} style={{ maxWidth: 280, position: "relative" }}>

                                {/* menu de 3 pontos */}
                                {isMe && <MessageMenu msg={m} />}

                                {/* conteúdo */}
                                {m.type === "image" && m.url && (
                                    <img src={m.url} alt="img"
                                        style={{ maxWidth: 250, borderRadius: 8 }} />
                                )}

                                {m.type === "video" && m.url && (
                                    <video src={m.url} controls style={{ maxWidth: 250, borderRadius: 8 }} />
                                )}

                                {m.type === "audio" && m.url && (
                                    <audio src={m.url} controls />
                                )}

                                {m.type === "file" && m.url && (
                                    <a href={m.url} target="_blank" rel="noreferrer">{m.url.split("/").pop()}</a>
                                )}

                                {m.type === "text" && (
                                    <div style={{ whiteSpace: "pre-wrap" }}>
                                        {m.text}
                                    </div>
                                )}

                                {/* editado */}
                                {m.edited && (
                                    <div style={{ fontSize: 10, marginTop: 4, opacity: 0.6 }}>
                                        (editada)
                                    </div>
                                )}

                                {/* hora + status */}
                                <div className="hora" style={{
                                    display: "flex",
                                    alignItems: "center",
                                    justifyContent: "flex-end",
                                    gap: 4
                                }}>
                                    {formatTime(m.createdAt)}
                                    {renderStatus(m)}
                                </div>

                            </div>
                        </div>
                    );
                })}
            </div>


            {/* RODAPÉ DO INPUT */}
            <div className="chat-input" style={{ flexDirection: "column", gap: 8 }}>

                {/* PREVIEW */}
                {previewUrl && (
                    <div style={{ display: "flex", gap: 10 }}>
                        {(file.type.startsWith("image/")) && (
                            <img src={previewUrl} alt="prev"
                                style={{ width: 120, height: 80, objectFit: "cover", borderRadius: 8 }} />
                        )}
                        {file.type.startsWith("video/") && (
                            <video src={previewUrl} style={{ width: 140 }} controls></video>
                        )}

                        <button onClick={() => {
                            URL.revokeObjectURL(previewUrl);
                            setPreviewUrl("");
                            setFile(null);
                        }}>Remover</button>
                    </div>
                )}

                {/* GIF */}
                {showGifModal && (
                    <div style={{
                        padding: 10,
                        border: "1px solid #ccc",
                        borderRadius: 8
                    }}>
                        <input
                            value={gifUrl}
                            onChange={(e) => setGifUrl(e.target.value)}
                            placeholder="URL do GIF"
                            style={{ width: "80%" }}
                        />
                        <button onClick={() => setShowGifModal(false)}>Fechar</button>
                    </div>
                )}

                <div style={{ display: "flex", gap: 8, alignItems: "center" }}>

                    <button onClick={() => setShowEmoji(v => !v)}>😊</button>

                    {showEmoji && (
                        <div style={{ position: "absolute", bottom: 90, left: 20, zIndex: 20 }}>
                            <Picker
                                onEmojiClick={(e, d) => setText(prev => prev + d.emoji)}
                            />
                        </div>
                    )}

                    <input
                        value={editingMessage ? editText : text}
                        onChange={e => {
                            if (editingMessage) setEditText(e.target.value);
                            else setText(e.target.value);
                        }}
                        placeholder={editingMessage ? "Editando..." : "Mensagem..."}
                        style={{ flex: 1, padding: 12 }}
                    />

                    <label>
                        📎
                        <input type="file"
                            style={{ display: "none" }}
                            accept="image/*,video/*,audio/*,*/*"
                            onChange={onSelectFile}
                        />
                    </label>

                    <button onClick={() => setShowGifModal(v => !v)}>GIF</button>

                    {/* botões editar */}
                    {editingMessage ? (
                        <>
                            <button onClick={cancelEdit}>Cancelar</button>
                            <button onClick={saveEdit} style={{ background: "#075E54", color: "#fff" }}>Salvar</button>
                        </>
                    ) : (
                        <button onClick={send} disabled={uploading}
                            style={{ background: "#075E54", color: "#fff" }}>
                            Enviar
                        </button>
                    )}
                </div>

            </div>
        </>
    );
}
